removed_rules.rule_before:
.page-index .hero h1{
 font-family:"Novoferma Poster",var(--font-display);
 font-weight:850;
 font-size:clamp(51px,7.4vw,108px);
 letter-spacing:-.022em;
 line-height:.97;
 text-wrap:initial;
}

.hero-copy > p.hero-note {
  display: block;
  max-width: 30ch;
  margin-top: 25px;
  color: var(--type-ink);
  font-family: var(--font-hand);
  font-size: clamp(30px, 2.55vw, 38px);
  font-weight: 500;
  line-height: 1.06;
  letter-spacing: -.025em;
  transform: rotate(var(--hand-angle));
  transform-origin: left center;
}

.hero + .hero-signature {
  min-height: 0;
  padding-block: 30px 32px;
  border-bottom: 1px solid var(--line);
  gap: 32px;
}

.serving-content figcaption.hand {
  font-size: var(--hand-caption);
  line-height: 1.05;
  color: var(--brown);
}

.hero + .hero-signature {
    display:grid;
    grid-template-columns:minmax(0,1fr) minmax(112px,.42fr);
    align-items:center;
    gap:14px;
    padding-block:27px 30px;
  }

.hero-copy > p.hero-note {
    max-width: 27ch;
    margin-top: 22px;
    font-size: clamp(29px, 8.1vw, 34px);
    line-height: 1.08;
  }
